SELECT DATE_FORMAT(MIN(mkt.TRADEDATE), '%Y-%m-%d') AS `起始交易日`, DATE_FORMAT(MAX(mkt.TRADEDATE), '%Y-%m-%d') AS `截至交易日`, idx_info.INDX_SNAME AS `指数名称`, idx_info.INDX_CODE AS `指数代码`, ROUND(AVG(mkt.TVALUE) / 100000000, 2) AS `日均成交额(亿)` FROM GET_INDX_GEN_INFO idx_info INNER JOIN INDX_MKT mkt ON idx_info.INNER_CODE = mkt.INNER_CODE WHERE idx_info.INDX_SNAME LIKE '%中证军工%' AND idx_info.USE_STATUS = '使用' AND idx_info.ISVALID = 1 AND mkt.TRADEDATE >= '2026-01-01' AND mkt.ISVALID = 1 GROUP BY idx_info.INDX_SNAME, idx_info.INDX_CODE;
